use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Finds the end of a token in `input`, treating `\\<char>` as an escaped"] # [doc = " character that is part of the token (not a boundary)."] # [doc = ""] # [doc = " Returns the byte offset of the first unescaped whitespace character, or"] # [doc = " the length of `input` if no unescaped whitespace is found."] fn find_token_end (input : & str) -> usize { let mut escaped = false ; for (i , c) in input . char_indices () { if escaped { escaped = false ; continue ; } if c == '\\' { escaped = true ; continue ; } if c . is_whitespace () { return i ; } } input . len () }